"""Assemble results/summary.md: one direct answer per question, from the result tables."""
from __future__ import annotations

import numpy as np
import pandas as pd

from .common import RESULTS


def _read(name):
    p = RESULTS / f"{name}.csv"
    return pd.read_csv(p) if p.exists() else None


def _fmt(x, unit="d"):
    return "never (≤10 yr)" if not np.isfinite(x) else (f"{x:.0f} {unit}" if x >= 10 else f"{x:.1f} {unit}")


def write():
    L = ["# Cattle Run cislunar solar-sail trade study — results summary", "",
         "Generated by `python -m cislunar_sail.run_all`. Reference spacecraft: 60 kg bus, "
         "characteristic acceleration a_c = 0.2 mm/s² unless stated; hybrids add 10 mN / 1500 s SEP with 8 kg Xe. "
         "Figures in `figures/`, full tables in `results/`.", ""]

    q1 = _read("q1_earth_to_cislunar")
    if q1 is not None:
        L += ["## Q1 — Transit to cislunar space (apogee ≥ 300,000 km)", "",
              "| Start | Conventional | Double-sided | Hybrid fixed SEP | Hybrid gimballed SEP | Spin-stabilised |",
              "|---|---|---|---|---|---|"]
        r = q1[np.isclose(q1.ac_mm_s2, 0.2)]
        for s in ["LEO 600 km", "LEO 1000 km", "MEO 8000 km", "GTO", "GEO", "TLI"]:
            cells = []
            for a in ["Conventional sail", "Double-sided sail", "Hybrid (fixed SEP)", "Hybrid (gimballed SEP)", "Spin-stabilised sail"]:
                v = r[(r.start == s) & (r.arch == a)].median_days
                cells.append(_fmt(v.iloc[0]) if len(v) else "–")
            L.append(f"| {s} | " + " | ".join(cells) + " |")
        L += ["", "Spin-stabilised (inertially fixed per orbit) sails cannot raise a planet-centred orbit: "
              "the work done over a revolution cancels. Transit time scales ≈ 1/a_c (see `q1_transit_vs_ac`).", ""]

    q2 = _read("q2_launch_inclination")
    if q2 is not None:
        L += ["## Q2 — Launch inclination", ""]
        for s in q2.start.unique():
            d = q2[(q2.start == s) & (q2.arch == "Conventional sail")]
            spread = (d.median_days.max() - d.median_days.min()) / d.median_days.mean() * 100
            best = d.loc[d.best_plane_offset.idxmin()] if "best_plane_offset" in d else None
            L.append(f"- From {s}: transit time varies only {spread:.0f}% across inclinations "
                     f"({d.median_days.min():.0f}–{d.median_days.max():.0f} d). "
                     + (f"Lowest achievable arrival-plane offset from the Moon's orbit: {best.best_plane_offset:.0f}° at "
                        f"i = {best.inc_deg:g}° (with RAAN/launch time chosen)." if best is not None else ""))
        L += ["- Recommendation: choose inclination to match the lunar plane (≈ lunar inclination to the equator at "
              "launch epoch) and pick launch time (RAAN) for plane alignment; transit time is insensitive.", ""]

    q3 = _read("q3_cislunar_transfers")
    if q3 is not None:
        L += ["## Q3 — Transit between cislunar orbits (median over Sun phase, days)", "",
              "| From → To | Conventional | Hybrid gimballed |", "|---|---|---|"]
        for (s, d), g in q3.groupby(["src", "dst"]):
            c = g[g.arch == "Conventional sail"].median_days
            h = g[g.arch == "Hybrid (gimballed SEP)"].median_days
            q3f = lambda v: f"{v:.0f} d" if np.isfinite(v) else "n/c (≤160 d)"
            L.append(f"| {s} → {d} | {q3f(c.iloc[0]) if len(c) else 'n/c (≤160 d)'} | {q3f(h.iloc[0]) if len(h) else 'n/c (≤160 d)'} |")
        llo = _read("q3_llo_spiral")
        if llo is not None:
            for a, g in llo.groupby("arch"):
                L.append(f"\n- Lunar capture orbit (15,000 km) → 100 km polar LLO, {a}: {g.days.median():.0f} d "
                         f"(Xe used {g.prop_kg.median():.1f} kg)")
        L += ["", "n/c = no validated transfer up to 160 d in the TOF grid. Times are feasible upper bounds "
              "from a multi-start minimum-time search on a discrete TOF grid.", ""]

    q4 = _read("q4_pole_sitter")
    if q4 is not None:
        L += ["## Q4 — Lunar south-pole sitter", "",
              f"- Minimum acceleration to hover at any point with the south pole ≥10° above the horizon: "
              f"{q4.min_req_accel_visible_mm_s2.min():.2f} mm/s², mostly *out of the lunar orbit plane*, which a "
              "sail (Sun ≈ in plane) supplies at ≤ ⅓ efficiency.",
              f"- No static sail-only pole-sitter exists up to a_c = {q4.ac_mm_s2.max():g} mm/s² (practical ceiling for CP1 film).",
              f"- Hybrid: sail covers part of the demand; SEP must still supply ≈ "
              f"{q4.min_dv_per_year_km_s.min():.1f}–{q4.min_dv_per_year_km_s.max():.1f} km/s per year "
              f"(≈ {q4.prop_kg_per_year_100kg_isp1500.min():.0f}–{q4.prop_kg_per_year_100kg_isp1500.max():.0f} kg Xe per 100 kg per year at 1500 s).",
              "- Implication: use periodic south-pole-viewing orbits (southern L1/L2 halos / NRHO, sail-displaced "
              "periodic orbits) rather than a static pole-sitter.", ""]

    q5 = _read("q5_in_irons")
    if q5 is not None:
        L += ["## Q5 — In-irons (no-travel) region", "", "| Architecture | In-irons solid angle | Worst-direction accel (mm/s²) |",
              "|---|---|---|"]
        for _, r in q5.iterrows():
            L.append(f"| {r.arch} | {r.irons_solid_angle_frac * 100:.0f}% of directions | {r.min_dir_accel_mm_s2:.3f} |")
        L += ["", "In-irons = < 10% of a_c available along the direction.", ""]

    q6 = _read("q6_field_of_view")
    if q6 is not None:
        L += ["## Q6 — Field of view (L2 halo / DRO, 180 d of operational sail attitudes)", ""]
        for orb in q6.orbit.unique():
            for t in ["Earth (antenna, 20° beam)", "Moon (camera, 10° FOV)"]:
                d = q6[(q6.orbit == orb) & (q6.target == t) & (q6.placement == "Bus behind sail")].set_index("gimbal_deg").coverage
                L.append(f"- {orb}, {t}: fixed bus {d.get(0, np.nan)*100:.0f}% of time; "
                         f"±30° gimbal {d.get(30, np.nan)*100:.0f}%; ±60° {d.get(60, np.nan)*100:.0f}%; ±90° {d.get(90, np.nan)*100:.0f}%")
        sa = q6[q6.target.str.startswith("Sail-mounted")].coverage
        L += [f"- Solar arrays: a bus behind the sail never sees the Sun; sail-mounted thin-film arrays deliver "
              f"{sa.mean()*100:.0f}% of normal-incidence power on average.", ""]

    q7 = _read("q7_maneuvers")
    if q7 is not None:
        L += ["## Q7 — Maneuverability (median days; Xe kg)", "", "| Maneuver | " + " | ".join(q7.arch.unique()) + " |",
              "|---|" + "---|" * q7.arch.nunique()]
        for m, g in q7.groupby("maneuver"):
            L.append(f"| {m} | " + " | ".join(f"{_fmt(r.median_days)}; {r.prop_kg:.1f} kg; e={r.e_final:.3f}" for _, r in g.iterrows()) + " |")
        L.append("")

    q8 = _read("q8_lowest_orbit")
    if q8 is not None:
        L += ["## Q8 — Lowest acceptable demonstration orbit (lowest altitude with ≥ +10 km net raise in 30 d, 28.5°)", "",
              "| a_c (mm/s²) | Solar min | Moderate | Solar max |", "|---|---|---|---|"]
        d = q8[(q8.arch == "Conventional sail") & (q8.plane == "28.5° (Cape)")]
        for ac, g in d.groupby("ac_mm_s2"):
            v = g.set_index("atmosphere").lowest_demo_km
            L.append(f"| {ac:g} | {v.get('min', np.nan):.0f} km | {v.get('moderate', np.nan):.0f} km | {v.get('max', np.nan):.0f} km |")
        L += ["", "Sail drag and SRP both scale with A/m, so the crossover altitude is nearly independent of sail size; "
              "it is set by thermospheric density (solar cycle).", ""]
        for arch in ["Double-sided sail", "Retractable sail", "Hybrid (gimballed SEP)"]:
            a = q8[(q8.arch == arch) & (q8.plane == "28.5° (Cape)") & (q8.atmosphere == "moderate") & np.isclose(q8.ac_mm_s2, 0.2)]
            b = d[(d.atmosphere == "moderate") & np.isclose(d.ac_mm_s2, 0.2)]
            if len(a) and len(b):
                L.append(f"- {arch} vs conventional (a_c 0.2, moderate): {a.lowest_demo_km.iloc[0]:.0f} km vs {b.lowest_demo_km.iloc[0]:.0f} km")
        L += ["- A single-sided sail's absorptive (Cr) back face can fly edge-on to the airflow while still taking "
              "photon momentum along the light direction; a fully specular double-sided sail cannot decouple thrust "
              "from drag, so it performs worse in drag-limited LEO.", ""]

    att = _read("attitude_momentum")
    if att is not None:
        r = att[(att.cp_offset_pct == 0.5) & (att.gimbal_arm_m == 1.0)].iloc[0]
        L += ["## Attitude / momentum management", "",
              f"- A 0.5% CP–CM offset produces {r.disturbance_mNm:.1f} mN·m ({r.momentum_Nms_per_day:.0f} N·m·s/day): "
              "far beyond reaction-wheel capacity, so continuous trim is mandatory.",
              f"- Gimballed-bus CM shift: {r.cmt_gimbal_deg_required:.0f}° on a 1 m arm. "
              f"Electrochromic film: {r.rcd_area_frac_dCn0p5*100:.0f}% of sail area at ΔCn = 0.5 "
              f"({r.rcd_area_frac_dCn0p8*100:.0f}% at 0.8). Both scale with SRP, so authority holds at every cone angle.",
              "- Electrochromic films trim pitch/yaw continuously (no wheel desaturation); roll about the sail normal "
              "still needs wheels, vanes, or twisted/angled film elements.", ""]

    RESULTS.mkdir(parents=True, exist_ok=True)
    p = RESULTS / "summary.md"
    p.write_text("\n".join(L))
    return p
